module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg reset;
    reg data;
    wire start_shifting;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .data(data),
        .start_shifting(start_shifting)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to apply a single bit and check output
    task apply_bit(input bit val, input bit expected_out);
        begin
            data = val;
            @(posedge clk);
            #1; // Allow output to update
            if (start_shifting !== expected_out) begin
                $display("Time %0t: Mismatch! data=%b, expected start_shifting=%b, got=%b", 
                         $time, val, expected_out, start_shifting);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 0;
        data = 0;

        // -----------------------------------------------------------------
        // Test 1: Reset behavior
        // -----------------------------------------------------------------
        @(posedge clk);
        reset = 1;
        @(posedge clk);
        #1;
        if (start_shifting !== 1'b0) begin
            $display("Time %0t: Reset failed to clear start_shifting. Got=%b", $time, start_shifting);
            errors = errors + 1;
        end

        reset = 0;
        @(posedge clk);
        if (start_shifting !== 1'b0) begin
            $display("Time %0t: start_shifting became high unexpectedly after reset deassertion.", $time);
            errors = errors + 1;
        end

        // -----------------------------------------------------------------
        // Test 2: Non-matching sequence (1 0 0 0) -> should remain 0
        // -----------------------------------------------------------------
        apply_bit(1'b1, 1'b0);
        apply_bit(1'b0, 1'b0);
        apply_bit(1'b0, 1'b0);
        apply_bit(1'b0, 1'b0);

        // -----------------------------------------------------------------
        // Test 3: Partial sequence matching with overlap (1 1 0 1)
        // Stream: 1, 1, 0, 1 -> Match on the last bit
        // -----------------------------------------------------------------
        apply_bit(1'b1, 1'b0); // 1
        apply_bit(1'b1, 1'b0); // 1 1
        apply_bit(1'b0, 1'b0); // 1 1 0
        apply_bit(1'b1, 1'b1); // 1 1 0 1 -> Should assert start_shifting = 1

        // -----------------------------------------------------------------
        // Test 4: Once found, stay high forever until reset (even with 0s/1s)
        // -----------------------------------------------------------------
        apply_bit(1'b0, 1'b1);
        apply_bit(1'b0, 1'b1);
        apply_bit(1'b1, 1'b1);

        // -----------------------------------------------------------------
        // Test 5: Synchronous reset check while running
        // -----------------------------------------------------------------
        reset = 1;
        @(posedge clk);
        #1;
        if (start_shifting !== 1'b0) begin
            $display("Time %0t: Synchronous reset failed while running.", $time);
            errors = errors + 1;
        end
        reset = 0;
        @(posedge clk);
        if (start_shifting !== 1'b0) begin
            $display("Time %0t: start_shifting active after reset release.", $time);
            errors = errors + 1;
        end

        // -----------------------------------------------------------------
        // Test 6: Another match with leading noise (0 1 1 0 1)
        // -----------------------------------------------------------------
        apply_bit(1'b0, 1'b0);
        apply_bit(1'b1, 1'b0);
        apply_bit(1'b1, 1'b0);
        apply_bit(1'b0, 1'b0);
        apply_bit(1'b1, 1'b1);

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
